// Declarative (React) — you describe the end state, React handles the DOM updates
function Counter() {
  const [count, setCount] = useState(0);
  return <button onClick={() => setCount(count + 1)}>Clicked {count}</button>;
}

// A component is literally just a function returning JSX
function Greeting(props) {
  return <h1>Hello, {props.name}!</h1>;
}

// Used like an HTML tag
<Greeting name="Priya" />
<Greeting name="Rahul" />

// What you write:
const element = <h1 className="greeting">Hello, world!</h1>;

// What it actually compiles to under the hood:
const element = React.createElement(
  "h1",
  { className: "greeting" },
  "Hello, world!"
);

// 1. Must return a SINGLE root element (or a Fragment)
// WRONG:
return (
  <h1>Title</h1>
  <p>Text</p>
);
// RIGHT:
return (
  <div>
    <h1>Title</h1>
    <p>Text</p>
  </div>
);

// 2. Use {} to embed any JavaScript expression
const name = "Priya";
const element = <h1>Hello, {name}! 2 + 2 = {2 + 2}</h1>;

// 3. className instead of class (class is a reserved JS keyword)
<div className="container"></div>

// 4. Self-closing tags need a slash
<img src="photo.jpg" />
<br />

// 5. camelCase for attributes (onclick → onClick, tabindex → tabIndex)
<button onClick={handleClick}>Click</button>

// Basic functional component
