};

// Implicit return for a single expression — common shorthand
const Welcome = () => <h1>Welcome to React!</h1>;

// Accepting props
function Welcome({ name }) {   // destructuring props directly in the parameter
  return <h1>Welcome, {name}!</h1>;
}

