import React from "react";

class Welcome extends React.Component {
  render() {
    return <h1>Welcome, {this.props.name}!</h1>;
  }
}

// Used exactly like a functional component
<Welcome name="Priya" />

class Counter extends React.Component {
  constructor(props) {
    super(props);           // required — sets up `this.props` correctly
    this.state = { count: 0 };
  }

  increment = () => {
    this.setState({ count: this.state.count + 1 });
  };

  render() {
    return (
      <button onClick={this.increment}>
        Clicked {this.state.count} times
      </button>
    );
  }
}

import { useState } from "react";

function Counter() {
  const [count, setCount] = useState(0);  // [currentValue, updaterFunction]

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>Increment</button>
    </div>
  );
}

// WRONG — mutating directly, React won't detect this change, no re-render
count++;

// RIGHT — always go through the setter
setCount(count + 1);

function Greeting(props) {
  return <h1>Hello, {props.name}! You are {props.age} years old.</h1>;
}

// Parent passes data via attributes, just like HTML attributes
<Greeting name="Priya" age={27} />

function Greeting(props) {
  props.name = "Changed";  // ❌ this would be a mutation bug — never do this
  return <h1>{props.name}</h1>;
}

function Parent() {
  const handleClick = () => console.log("Child clicked!");
  return <Child onButtonClick={handleClick} />;
}
function Child({ onButtonClick }) {
  return <button onClick={onButtonClick}>Click me</button>;
}

function Parent() {
  const [count, setCount] = useState(0);  // STATE — Parent owns and can change this

  return <Child currentCount={count} />;  // passed down as a PROP — Child can only read it
}

function Child({ currentCount }) {  // receives it as a prop, read-only
  return <p>Count is: {currentCount}</p>;
}
